def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bikes = image_patch.find("bike")
    kids = image_patch.find("kid")

    if not bikes or not kids:
        return image_patch

    bike_centers = [(bike.left + bike.right) / 2 for bike in bikes]
    kid_centers = [(kid.left + kid.right) / 2 for kid in kids]

    min_distance = float('inf')
    best_bike = None

    for i, bike_center in enumerate(bike_centers):
        for j, kid_center in enumerate(kid_centers):
            if abs(bike_center - kid_center) < min_distance:
                min_distance = abs(bike_center - kid_center)
                best_bike = bikes[i]

    return best_bike

